const theme = {
    primary: "rgb(201, 168, 76)",   // gold
    secondary: "#000000",           // black
    background: "#000000",
    text: "#ffffff",
    border: "#2a2a2a",
  
    buttonBg: "rgb(201, 168, 76)",
    buttonText: "#000000",
  
    footerBg: "#000000",
    footerText: "#cccccc",
    color: "#fff"
  };
  
  export default theme;
